// Expo config plugin: tunes android/gradle.properties so native builds fit on
// an 8 GB laptop and only compile the CPU architectures that are needed.
// android/ is regenerated by `expo prebuild`, so the settings live here.
//
// Usage in app.json / app.config:
//   "./plugins/with-android-build-tuning.js"
//   ["./plugins/with-android-build-tuning.js", { "easArchitectures": "arm64-v8a" }]
//
// Options:
//   localArchitectures  ABIs for builds on this machine (default arm64-v8a;
//                       `expo run:android` narrows to the connected phone anyway)
//   easArchitectures    ABIs for EAS builds (default armeabi-v7a,arm64-v8a).
//                       x86/x86_64 only exist for emulators, so they are left
//                       out: that halves native compile work and APK size.
const { withGradleProperties } = require('expo/config-plugins');

module.exports = function withAndroidBuildTuning(config, options = {}) {
  const {
    localArchitectures = 'arm64-v8a',
    easArchitectures = 'armeabi-v7a,arm64-v8a',
  } = options;

  const properties = {
    // One JVM instead of two: compile Kotlin inside the Gradle daemon rather
    // than a separate Kotlin daemon that would take its own ~2 GB heap.
    'org.gradle.jvmargs': '-Xmx2560m -XX:MaxMetaspaceSize=512m',
    'kotlin.compiler.execution.strategy': 'in-process',
    // Free the daemon's memory 15 minutes after the last build (default 3 h).
    'org.gradle.daemon.idletimeout': '900000',
    // Reuse task outputs across builds and after `expo prebuild --clean`.
    'org.gradle.caching': 'true',
    // EAS sets EAS_BUILD=true on its builders (cloud and `eas build --local`).
    'reactNativeArchitectures': process.env.EAS_BUILD ? easArchitectures : localArchitectures,
  };

  return withGradleProperties(config, (config) => {
    const props = config.modResults;
    for (const [key, value] of Object.entries(properties)) {
      const existing = props.find(p => p.type === 'property' && p.key === key);
      if (existing)
        existing.value = value;
      else
        props.push({ type: 'property', key, value });
    }
    return config;
  });
};
